buggy.gh61617_distinguish_nan_na_examples_exam:
import pandas as pd
import numpy as np

# Ensure numpy printing doesn't matter; capture outputs as raw strings.

def as_result_or_exc(fn):
    try:
        return {"ok": True, "value": fn()}
    except Exception as err:
        return {"ok": False, "exc_type": type(err).__name__, "exc_message": str(err)}

cases = []
for using_nan_is_na in [True, False]:
    pd.set_option('future.distinguish_nan_and_na', using_nan_is_na)

    dtype = pd.StringDtype(storage='pyarrow')
    arr = pd.array([np.nan, pd.NA, 3.0], dtype='Float64')

    def ex1():
        return arr.astype(dtype).tolist()

    df = pd.DataFrame({'a': pd.array([np.nan, pd.NA, 3.0], dtype='Float64'), 'b': 'c'})
    def ex2():
        return df.to_csv(index=False)

    ser = pd.Series((1, pd.NA, 0), index=['a','b','c'], dtype='Float64', name='x')
    ser = ser / ser
    def ex3():
        return ser.to_csv()

    cases.append({
        "using_nan_is_na": using_nan_is_na,
        "ex1": as_result_or_exc(ex1),
        "ex2": as_result_or_exc(ex2),
        "ex3": as_result_or_exc(ex3),
    })

# The probe framework requires at least one numeric/structured record; record whole structure.
probe('results', cases)

